  const date = corrected?.date ?? c.date;
  const mode = settingOn(settings, 'rounding', date);
  if (mode === 'half-up') return true;
  if (mode === 'half-even') return false;
  const policy = settings === undefined ? undefined : settings.policyDate ?? today;
